import os,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
for c in range(17):
    colin=[inp[r][c] for r in range(17)]
    colout=[out[r][c] for r in range(17)]
    if any(colin) or any(colout):
        print(c, 'in:',colin)
        print(c, 'out:',colout)

def transform(g):
    g=[row[:] for row in g]
    h=len(g); w=len(g[0])
    marked=[c for c in range(w) if g[h-1][c]!=0]
    for c in marked:
        for r in range(h):
            for r2 in range(r,h):
                if g[r2][c]!=0:
                    g[r][c]=g[r2][c]; break
    return g
# verify demo
t=transform(G['Demo pair 1 input'])
print(t==G['Demo pair 1 output'])
import json
print(json.dumps(transform(G['Test input'])))
